#include "net_route.h"
int net_route_add(struct net_routes *t,const struct net_route *r){uint32_t inverse;if(!t||!r||t->count>=NET_MAX_ROUTES||!r->active||(r->prefix&~r->mask))return -1;inverse=~r->mask;if(inverse&(inverse+1U))return -1;for(uint32_t i=0;i<t->count;i++)if(t->entries[i].prefix==r->prefix&&t->entries[i].mask==r->mask&&t->entries[i].interface_id==r->interface_id)return -1;t->entries[t->count++]=*r;return 0;}
int net_route_remove(struct net_routes *t,uint32_t p,uint32_t m,uint32_t iface){if(!t)return -1;for(uint32_t i=0;i<t->count;i++)if(t->entries[i].prefix==p&&t->entries[i].mask==m&&t->entries[i].interface_id==iface){for(uint32_t j=i+1;j<t->count;j++)t->entries[j-1]=t->entries[j];t->count--;return 0;}return -1;}
int net_route_lookup(const struct net_routes *t,uint32_t dst,struct net_route *out){if(!t||!out)return -1;int found=0;uint32_t best=0;for(uint32_t i=0;i<t->count;i++){const struct net_route *r=&t->entries[i];if(!r->active||(dst&r->mask)!=r->prefix)continue;uint32_t bits=0;for(uint32_t m=r->mask;m;m<<=1)bits++;if(!found||bits>best||(bits==best&&r->metric<out->metric)){*out=*r;best=bits;found=1;}}return found?0:-1;}
